#!/bin/bash
# W2_batch.sh <key> [<key> ...]   per asset: build + check + report + preview; if every route passes and the cave is sealed: export + uv check (2048).
# One Blender job at a time (the steps run one after the other).  Do not edit this file or W2_queue.sh while it runs.
HERE="$(cd "$(dirname "$0")" && pwd -W)"
for k in "$@"; do
  "$HERE/W2_queue.sh" "$k" bcrp
  OK=$(python -I - "$HERE" "$k" <<'PY'
import sys, json
here, key = sys.argv[1], sys.argv[2]
sys.path.insert(0, here)
import W2_assets as A
A.build('crack')
name = A.build(key)[0].name
try:
    d = json.load(open(here + '/results/W2_check_%s.json' % name))
    ok = all(r.get('PASS') for r in d['routes'].values()) and d['leak_test'].get('sealed')
except Exception:
    ok = False
print('yes' if ok else 'no')
PY
)
  echo "BATCH $k checks pass: $OK"
  if [ "$OK" = "yes" ]; then "$HERE/W2_queue.sh" "$k" eu; fi
done
echo "BATCH DONE"
